17	/// Lay this out as an unbreakable block.
18	#[typst_macros::time(name = "block", span = elem.span())]
19	pub fn layout_single_block(
20	    elem: &Packed<BlockElem>,
21	    engine: &mut Engine,
22	    locator: Locator,
23	    styles: StyleChain,
24	    region: Region,
25	) -> SourceResult<Frame> {
26	    // Fetch sizing properties.
27	    let width = elem.width.get(styles);
28	    let height = elem.height.get(styles);
29	    let inset = elem.inset.resolve(styles).unwrap_or_default();
30	
31	    // Build the pod regions.
32	    let pod = unbreakable_pod(&width.into(), &height, &inset, styles, region.size);
33	
34	    // Layout the body.
35	    let body = elem.body.get_ref(styles);
36	    let mut frame = match body {
37	        // If we have no body, just create one frame. Its size will be
38	        // adjusted below.
39	        None => Frame::hard(Size::zero()),
40	
41	        // If we have content as our body, just layout it.
42	        Some(BlockBody::Content(body)) => {
43	            crate::layout_frame(engine, body, locator.relayout(), styles, pod)?
44	        }
45	
46	        // If we have a child that wants to layout with just access to the
47	        // base region, give it that.
48	        Some(BlockBody::SingleLayouter(callback)) => {
49	            callback.call(engine, locator, styles, pod)?
50	        }
51	
52	        // If we have a child that wants to layout with full region access,
53	        // we layout it.
54	        Some(BlockBody::MultiLayouter(callback)) => {
55	            let expand = (pod.expand | region.expand) & pod.size.map(Abs::is_finite);
56	            let pod = Region { expand, ..pod };
57	            callback.call(engine, locator, styles, pod.into())?.into_frame()
58	        }
59	    };
60	
61	    // Explicit blocks are boundaries for gradient relativeness.
62	    if matches!(body, None | Some(BlockBody::Content(_))) {
63	        frame.set_kind(FrameKind::Hard);
64	    }
65	
66	    // Enforce a correct frame size on the expanded axes. Do this before
67	    // applying the inset, since the pod shrunk.
68	    frame.set_size(pod.expand.select(pod.size, frame.size()));
69	
70	    // Apply the inset.
71	    if !inset.is_zero() {
72	        crate::pad::grow(&mut frame, &inset);
73	    }
74	
75	    // Prepare fill and stroke.
76	    let fill = elem.fill.get_cloned(styles);
77	    let stroke = elem
78	        .stroke
79	        .resolve(styles)
80	        .unwrap_or_default()
81	        .map(|s| s.map(Stroke::unwrap_or_default));
82	
83	    // Only fetch these if necessary (for clipping or filling/stroking).
84	    let outset = LazyCell::new(|| elem.outset.resolve(styles).unwrap_or_default());
85	    let radius = LazyCell::new(|| elem.radius.resolve(styles).unwrap_or_default());
86	
87	    // Clip the contents, if requested.
88	    if elem.clip.get(styles) {
89	        frame.clip(clip_rect(frame.size(), &radius, &stroke, &outset));
90	    }
91	
92	    // Add fill and/or stroke.
93	    if fill.is_some() || stroke.iter().any(Option::is_some) {
94	        fill_and_stroke(&mut frame, fill, &stroke, &outset, &radius, elem.span());
95	    }
96	
97	    // Assign label to each frame in the fragment.
98	    if let Some(label) = elem.label() {
99	        frame.label(label);
100	    }
101	
102	    Ok(frame)
103	}
