105	/// Lay this out as a breakable block.
106	#[typst_macros::time(name = "block", span = elem.span())]
107	pub fn layout_multi_block(
108	    elem: &Packed<BlockElem>,
109	    engine: &mut Engine,
110	    locator: Locator,
111	    styles: StyleChain,
112	    regions: Regions,
113	) -> SourceResult<Fragment> {
114	    // Fetch sizing properties.
115	    let width = elem.width.get(styles);
116	    let height = elem.height.get(styles);
117	    let inset = elem.inset.resolve(styles).unwrap_or_default();
118	
119	    // Allocate a small vector for backlogs.
120	    let mut buf = SmallVec::<[Abs; 2]>::new();
121	
122	    // Build the pod regions.
123	    let pod = breakable_pod(&width.into(), &height, &inset, styles, regions, &mut buf);
124	
125	    // Layout the body.
126	    let body = elem.body.get_ref(styles);
127	    let mut fragment = match body {
128	        // If we have no body, just create one frame plus one per backlog
129	        // region. We create them zero-sized; if necessary, their size will
130	        // be adjusted below.
131	        None => {
132	            let mut frames = vec![];
133	            frames.push(Frame::hard(Size::zero()));
134	            if pod.expand.y {
135	                let mut iter = pod;
136	                while !iter.backlog.is_empty() {
137	                    frames.push(Frame::hard(Size::zero()));
138	                    iter.next();
139	                }
140	            }
141	            Fragment::frames(frames)
142	        }
143	
144	        // If we have content as our body, just layout it.
145	        Some(BlockBody::Content(body)) => {
146	            let mut fragment =
147	                crate::layout_fragment(engine, body, locator.relayout(), styles, pod)?;
148	
149	            // If the body is automatically sized and produced more than one
150	            // fragment, ensure that the width was consistent across all
151	            // regions. If it wasn't, we need to relayout with expansion.
152	            if !pod.expand.x
153	                && fragment
154	                    .as_slice()
155	                    .windows(2)
156	                    .any(|w| !w[0].width().approx_eq(w[1].width()))
157	            {
158	                let max_width =
159	                    fragment.iter().map(|frame| frame.width()).max().unwrap_or_default();
160	                let pod = Regions {
161	                    size: Size::new(max_width, pod.size.y),
162	                    expand: Axes::new(true, pod.expand.y),
163	                    ..pod
164	                };
165	                fragment = crate::layout_fragment(engine, body, locator, styles, pod)?;
166	            }
167	
168	            fragment
169	        }
170	
171	        // If we have a child that wants to layout with just access to the
172	        // base region, give it that.
173	        Some(BlockBody::SingleLayouter(callback)) => {
174	            let pod = Region::new(pod.base(), pod.expand);
175	            callback.call(engine, locator, styles, pod).map(Fragment::frame)?
176	        }
177	
178	        // If we have a child that wants to layout with full region access,
179	        // we layout it.
180	        //
181	        // For auto-sized multi-layouters, we propagate the outer expansion
182	        // so that they can decide for themselves. We also ensure again to
183	        // only expand if the size is finite.
184	        Some(BlockBody::MultiLayouter(callback)) => {
185	            let expand = (pod.expand | regions.expand) & pod.size.map(Abs::is_finite);
186	            let pod = Regions { expand, ..pod };
187	            callback.call(engine, locator, styles, pod)?
188	        }
189	    };
190	
191	    // Prepare fill and stroke.
192	    let fill = elem.fill.get_ref(styles);
193	    let stroke = elem
194	        .stroke
195	        .resolve(styles)
196	        .unwrap_or_default()
197	        .map(|s| s.map(Stroke::unwrap_or_default));
198	
199	    // Only fetch these if necessary (for clipping or filling/stroking).
200	    let outset = LazyCell::new(|| elem.outset.resolve(styles).unwrap_or_default());
201	    let radius = LazyCell::new(|| elem.radius.resolve(styles).unwrap_or_default());
202	
203	    // Fetch/compute these outside of the loop.
204	    let clip = elem.clip.get(styles);
205	    let has_fill_or_stroke = fill.is_some() || stroke.iter().any(Option::is_some);
206	    let has_inset = !inset.is_zero();
207	    let is_explicit = matches!(body, None | Some(BlockBody::Content(_)));
208	
209	    // Skip filling, stroking and labeling the first frame if it is empty and
210	    // a non-empty one follows.
211	    let mut skip_first = false;
212	    if let [first, rest @ ..] = fragment.as_slice() {
213	        skip_first = first.is_empty() && rest.iter().any(|frame| !frame.is_empty());
214	    }
215	
216	    // Post-process to apply insets, clipping, fills, and strokes.
217	    for (i, (frame, region)) in fragment.iter_mut().zip(pod.iter()).enumerate() {
218	        // Explicit blocks are boundaries for gradient relativeness.
219	        if is_explicit {
220	            frame.set_kind(FrameKind::Hard);
221	        }
222	
223	        // Enforce a correct frame size on the expanded axes. Do this before
224	        // applying the inset, since the pod shrunk.
225	        frame.set_size(pod.expand.select(region, frame.size()));
226	
227	        // Apply the inset.
228	        if has_inset {
229	            crate::pad::grow(frame, &inset);
230	        }
231	
232	        // Clip the contents, if requested.
233	        if clip {
234	            frame.clip(clip_rect(frame.size(), &radius, &stroke, &outset));
235	        }
236	
237	        // Add fill and/or stroke.
238	        if has_fill_or_stroke && (i > 0 || !skip_first) {
239	            fill_and_stroke(frame, fill.clone(), &stroke, &outset, &radius, elem.span());
240	        }
241	    }
242	
243	    // Assign label to each frame in the fragment.
244	    if let Some(label) = elem.label() {
245	        // Skip empty orphan frames, as a label would make them non-empty.
246	        for frame in fragment.iter_mut().skip(if skip_first { 1 } else { 0 }) {
247	            frame.label(label);
248	        }
249	    }
250	
251	    Ok(fragment)
252	}
